import presentation.support.*
import presentation.support.leaky.SheetBuilder

fun <T> generateExcel(
  path: String,
  rows: Sequence<T>,
  block: SheetBuilder<T>.() -> Unit,
) {
  val builder = SheetBuilder<T>()
  builder.block()
  writeWorkbook(path, rows, builder)
}

